"""Demo stub: ordinary least squares stands in for the sparse regression."""


def fit_line(xs, ys):
    n = len(xs)
    mean_x, mean_y = sum(xs) / n, sum(ys) / n
    var = sum((x - mean_x) ** 2 for x in xs)
    if var == 0:
        raise ValueError("x values must not all be equal")
    slope = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys)) / var
    return slope, mean_y - slope * mean_x

import math


def validate_table(times, rows):
    if len(times) < 3:
        raise ValueError("file is too small")
    if any(math.isnan(v) or math.isinf(v) for row in rows for v in row):
        raise ValueError("file contains NaN or infinite values")
    if any(b <= a for a, b in zip(times, times[1:])):
        raise ValueError("time must be strictly increasing")
    if any(len(row) != len(rows[0]) for row in rows):
        raise ValueError("columns do not match")

import unittest

from engine.check_datafile import validate_table
from engine.sindy_model import fit_line


class EngineTests(unittest.TestCase):
    def test_fit_recovers_known_line(self):
        slope, intercept = fit_line([0, 1, 2, 3], [1, 3, 5, 7])
        self.assertAlmostEqual(slope, 2.0)
        self.assertAlmostEqual(intercept, 1.0)

    def test_rejects_non_increasing_time(self):
        with self.assertRaises(ValueError):
            validate_table([0, 2, 1], [[1], [2], [3]])

    def test_rejects_nan(self):
        with self.assertRaises(ValueError):
            validate_table([0, 1, 2], [[1], [float("nan")], [3]])


if __name__ == "__main__":
    unittest.main()

